        }
}

func readCSV(cfg config.InputConfig, dir string) ([]*record.Record, error) {
        path := config.ResolvePath(dir, cfg.Path)
        f, err := os.Open(path)
        if err != nil {
                return nil, fmt.Errorf("input: %v", err)
        }
        defer f.Close()

        r := csv.NewReader(f)
        r.FieldsPerRecord = 0
        r.TrimLeadingSpace = true

        header, err := r.Read()
        if err == io.EOF {
                return nil, fmt.Errorf("input: empty CSV file")
        }
        if err != nil {
                return nil, fmt.Errorf("input: %v", err)
        }

        records := []*record.Record{}
        rowNum := 0
        for {
                row, err := r.Read()
                if err == io.EOF {
                        break
                }
                if err != nil {
                        return nil, fmt.Errorf("input: row %d: %v", rowNum+2, err)
                }
                rowNum++

                if len(row) != len(header) {
                        return nil, fmt.Errorf("input: row %d: expected %d fields got %d", rowNum+1, len(header), len(row))
                }

                rec := record.New()
                rec.InputRow = rowNum
                for i, col := range header {
                        rec.Set(col, row[i])
                }
                records = append(records, rec)
        }

        return records, nil
}

