		if b == '\n' || b == '\r' {
			continue
		}
		if b == ' ' || b == '\t' {
			continue
		}

		if err := r.UnreadByte(); err != nil {
			return nil, err
		}

		field, err := readSQLiteField(r)
		if err != nil {
			return nil, err
		}
		fields = append(fields, field)

		for {
			b, err := r.ReadByte()
			if err == io.EOF {
				return fields, nil
			}
			if err != nil {
				return nil, err
			}
			if b == ' ' || b == '\t' {
				continue
			}
			if b == ',' {
				break
			}
			if b == '\n' || b == '\r' {
				if err := r.UnreadByte(); err != nil {
					return nil, err
				}
				return fields, nil
			}
			return nil, fmt.Errorf("expected comma or newline between fields")
		}
	}
}

func readSQLiteField(r *bufio.Reader) (string, error) {
	b, err := r.ReadByte()
	if err != nil {
		return "", err
	}

	if b == '\'' {
		var sb strings.Builder
		sb.WriteByte(b)
		for {
			c, err := r.ReadByte()
			if err != nil {
				return "", fmt.Errorf("unterminated string literal")
			}
			sb.WriteByte(c)
			if c != '\'' {
				continue
			}

		nb, err := r.ReadByte()
		if err == io.EOF {
			return sb.String(), nil
		}
		if err != nil {
			return "", err
		}
		if nb == '\'' {
			sb.WriteByte(nb)
				continue
			}
			if err := r.UnreadByte(); err != nil {
				return "", err
			}
			return sb.String(), nil
		}
	}

	if err := r.UnreadByte(); err != nil {
		return "", err
	}

	var sb strings.Builder
	for {
		c, err := r.ReadByte()
		if err == io.EOF {
			return sb.String(), nil
		}
		if err != nil {
			return "", err
		}
		if c == ',' || c == '\n' || c == '\r' || c == ' ' || c == '\t' {
			if err := r.UnreadByte(); err != nil {
				return "", err
			}
			return sb.String(), nil
		}
		sb.WriteByte(c)
	}
}

func renderSQLiteValue(raw string) (string, error) {
	if raw == "NULL" {
		return "", nil
	}
	if len(raw) >= 2 && (raw[0] == 'X' || raw[0] == 'x') && raw[1] == '\'' && raw[len(raw)-1] == '\'' {
		return "", fmt.Errorf("BLOB values are not supported")
	}
	if len(raw) > 0 && raw[0] == '\'' {
		return unquoteSQLiteString(raw)
	}

	if _, err := strconv.ParseInt(raw, 10, 64); err == nil {
		return raw, nil
	}

	if f, err := strconv.ParseFloat(raw, 64); err == nil {
		if math.IsNaN(f) || math.IsInf(f, 0) {
			return "", fmt.Errorf("non-finite numeric value")
		}
		return formatFloat(f), nil
	}

	return raw, nil
}

func unquoteSQLiteString(raw string) (string, error) {
	if len(raw) < 2 || raw[0] != '\'' || raw[len(raw)-1] != '\'' {
		return "", fmt.Errorf("invalid string literal")
	}

	var b strings.Builder
	i := 1
	for i < len(raw)-1 {
		if raw[i] == '\'' {
			if i+1 < len(raw)-1 && raw[i+1] == '\'' {
				b.WriteByte('\'')
				i += 2
				continue
			}
			return "", fmt.Errorf("invalid string literal")
		}
		b.WriteByte(raw[i])
		i++
	}
	return b.String(), nil
}

func firstSQLiteError(stderr string) string {
	s := strings.TrimSpace(stderr)
	if s == "" {
		return "sqlite command failed"
	}
	if i := strings.IndexAny(s, "\n\r"); i >= 0 {
		return s[:i]
	}
	return s
}

func formatFloat(f float64) string {
	if f == float64(int64(f)) {
		return strconv.FormatInt(int64(f), 10)
	}
	return strconv.FormatFloat(f, 'g', -1, 64)
}
