package stage

import (
	"fmt"
	"io"
	"math"
	"strconv"
	"strings"

	"example.com/flowctl/internal/record"
)

type GroupAggregate struct {
	As     string
	Op     string
	Column string
}

type GroupStage struct {
	by         []string
	aggregates []GroupAggregate
}

func (s *GroupStage) Apply(in []*record.Record, stderr io.Writer, strict bool, stats *Stats) ([]*record.Record, error) {
	type groupState struct {
		keyParts []string
		firstRow int
		count    int
		sums     []float64
		mins     []float64
		maxs     []float64
		hasMin   []bool
		hasMax   []bool
	}

	order := []string{}
	keys := map[string]*groupState{}

	for _, r := range in {
		keyParts := make([]string, len(s.by))
		for i, col := range s.by {
			v, ok := r.Get(col)
			if !ok {
				return nil, fmt.Errorf("group: missing column %s", col)
			}
			keyParts[i] = v
		}
		key := strings.Join(keyParts, "\x00")

		st, exists := keys[key]
		if !exists {
			st = &groupState{
				keyParts: keyParts,
				firstRow: r.InputRow,
				sums:     make([]float64, len(s.aggregates)),
				mins:     make([]float64, len(s.aggregates)),
				maxs:     make([]float64, len(s.aggregates)),
				hasMin:   make([]bool, len(s.aggregates)),
				hasMax:   make([]bool, len(s.aggregates)),
			}
			keys[key] = st
			order = append(order, key)
		}
		st.count++

		for i, agg := range s.aggregates {
			if agg.Op == "count" {
				continue
			}

			v, ok := r.Get(agg.Column)
			if !ok {
				return nil, fmt.Errorf("group: missing column %s", agg.Column)
			}
			f, err := parseFloat(v)
			if err != nil {
				return nil, fmt.Errorf("group: non-numeric value in column %s at row %d", agg.Column, r.InputRow)
			}

			st.sums[i] += f
			if !st.hasMin[i] || f < st.mins[i] {
				st.mins[i] = f
				st.hasMin[i] = true
			}
			if !st.hasMax[i] || f > st.maxs[i] {
				st.maxs[i] = f
				st.hasMax[i] = true
			}
		}
	}

	out := make([]*record.Record, 0, len(order))
	for _, key := range order {
		st := keys[key]
		nr := record.New()
		nr.InputRow = st.firstRow

		for i, col := range s.by {
			nr.Set(col, st.keyParts[i])
		}

		for i, agg := range s.aggregates {
			switch agg.Op {
			case "count":
				nr.Set(agg.As, strconv.Itoa(st.count))
			case "sum":
				nr.Set(agg.As, formatFloat(st.sums[i]))
			case "min":
				nr.Set(agg.As, formatFloat(st.mins[i]))
			case "max":
				nr.Set(agg.As, formatFloat(st.maxs[i]))
			case "avg":
				if st.count == 0 {
					return nil, fmt.Errorf("group: avg of empty group")
				}
				nr.Set(agg.As, formatFloat(st.sums[i]/float64(st.count)))
			}
		}

		out = append(out, nr)
	}

	return out, nil
}

func buildGroup(idx int, sm map[string]interface{}) (Stage, error) {
	byRaw, ok := sm["by"]
	if !ok {
		return nil, fmt.Errorf("config: stage %d: group.by is required", idx)
	}
	by, err := toStringList(byRaw)
	if err != nil {
		return nil, fmt.Errorf("config: stage %d: group.by: %v", idx, err)
	}
	if len(by) == 0 {
		return nil, fmt.Errorf("config: stage %d: group.by must be non-empty", idx)
	}

	aggRaw, ok := sm["aggregates"]
	if !ok {
		return nil, fmt.Errorf("config: stage %d: group.aggregates is required", idx)
	}
	aggList, ok := aggRaw.([]interface{})
	if !ok {
		return nil, fmt.Errorf("config: stage %d: group.aggregates must be a list", idx)
	}
	if len(aggList) == 0 {
		return nil, fmt.Errorf("config: stage %d: group.aggregates must be non-empty", idx)
	}

	aggregates := make([]GroupAggregate, 0, len(aggList))
	seen := map[string]bool{}
	for i, item := range aggList {
		am, ok := item.(map[string]interface{})
		if !ok {
			return nil, fmt.Errorf("config: stage %d: group.aggregates entry %d must be a mapping", idx, i+1)
		}

		name, ok := getString(am, "as")
		if !ok || name == "" {
			return nil, fmt.Errorf("config: stage %d: group.aggregates entry %d: as is required", idx, i+1)
		}
		if seen[name] {
			return nil, fmt.Errorf("config: stage %d: group.aggregates entry %d: duplicate as %q", idx, i+1, name)
		}

		op, ok := getString(am, "op")
		if !ok || op == "" {
			return nil, fmt.Errorf("config: stage %d: group.aggregates entry %d: op is required", idx, i+1)
		}
		switch op {
		case "count", "sum", "min", "max", "avg":
		default:
			return nil, fmt.Errorf("config: stage %d: group.aggregates entry %d: op must be count, sum, min, max, or avg", idx, i+1)
		}

		col, hasCol := getString(am, "column")
		if op == "count" {
			if hasCol {
				return nil, fmt.Errorf("config: stage %d: group.aggregates entry %d: column must not be present for count", idx, i+1)
			}
		} else {
			if !hasCol || col == "" {
				return nil, fmt.Errorf("config: stage %d: group.aggregates entry %d: column is required", idx, i+1)
			}
		}

		aggregates = append(aggregates, GroupAggregate{As: name, Op: op, Column: col})
		seen[name] = true
	}

	return &GroupStage{by: by, aggregates: aggregates}, nil
}

func toStringList(v interface{}) ([]string, error) {
	list, ok := v.([]interface{})
	if !ok {
		return nil, fmt.Errorf("must be a list of strings")
	}
	out := []string{}
	for i, item := range list {
		s, ok := item.(string)
		if !ok {
			return nil, fmt.Errorf("entry %d must be a string", i+1)
		}
		out = append(out, s)
	}
	return out, nil
}

func formatFloat(f float64) string {
	if math.IsNaN(f) || math.IsInf(f, 0) {
		return strconv.FormatFloat(f, 'g', -1, 64)
	}
	if f == float64(int64(f)) {
		return strconv.FormatInt(int64(f), 10)
	}
	return strconv.FormatFloat(f, 'g', -1, 64)
}
